INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(114979, 'ruRU', '', 'Ты можешь приобрести сувениры и подарки у Сильверин, моей помощницы. Возможно, сделаешь это на выходе?', 24330),
(114980, 'ruRU', '', 'Это наш павильон для дегустации. Здесь мы подаём только лучшие сорта — многие из них подают во дворце!', 24330),
(114982, 'ruRU', '', 'Не стесняйся попробовать образцы, которые у нас есть сегодня. Мы продолжим экскурсию, когда закончишь.', 24330),
(114984, 'ruRU', '', 'Орден Серебряной Руки возродился. Его новые лидеры не позволят ему потерпеть крах.', 24330),
(114985, 'ruRU', '', 'Да, военный совет — хорошая идея. Силы Легиона распространяются по Расколотым островам. Мы не должны потерять там свой плацдарм!', 24330),
(115001, 'ruRU', '', '<Марго тревожно смотрит по сторонам, прежде чем склониться близко, чтобы прошептать тебе.>\n\nТалисра должна быть жива, если другие действуют в тенях. Кто ещё, кроме Первого Чародея, мог бы вдохновить на такие действия?\n\nСкажи мне — как она?', 24330),
(115002, 'ruRU', '', 'Насекомые? У тебя проблема с насекомыми?\n\n<Марго с любопытством смотрит на тебя мгновение.>\n\nНичего страшного. Видишь, ответ прямо перед тобой. Мана-змейки охотятся на насекомых, что охотятся на наши деревья. Они сохраняют наши драгоценные растения целыми, да и сами едят неплохо.\n\nЯ обязательно найду время в нашей экскурсии, чтобы ты мог их собрать.', 24330),
(115003, 'ruRU', '', 'Мне так спокойнее от этих слов. Впрочем, идём дальше.', 24330),
(115005, 'ruRU', '', 'Итак... зачем именно ты пришёл сюда? Это уж точно одно из наименее безопасных мест для членов сопротивления.', 24330),
(115007, 'ruRU', '', 'Они просто... я их ненавижу! Мы служим по их воле, иначе нас ждёт изгнание и смерть. Но я ничего не могу сделать, пока Великая Магистрикс стремится удержать эту область под контролем.\n\nУ тебя наверняка обширная сеть связей, чтобы добраться сюда. Сопротивление растёт? Способно ли оно по-настоящему противостоять Элизанде?', 24330),
(115009, 'ruRU', '', '<Марго вздыхает.>\n\nШансы против нас. Нас бьют и изгоняют на каждом шагу. Но ты и Первый Чародей всё ещё на нашей стороне. В это я могу поверить.\n\nЯ верю в Сумеречную Лилию.\n\nНо хватит об этом. Готов закончить нашу экскурсию?', 24330),
(115010, 'ruRU', '', 'Понятно... что ж, продолжим?', 24330),
(115012, 'ruRU', '', 'Ночь темна и полна демонов.', 24330),
(115014, 'ruRU', '', 'Легион идёт за каждым и за всем... Мы должны принять огни Азерота, если надеемся увидеть рассвет.', 24330),
(115021, 'ruRU', '', 'Здание, к которому мы сейчас подходим, называется Камерой Выдержки.', 24330),
(115022, 'ruRU', '', 'Мы предпочитаем сокращать этот процесс при помощи магии времени. Такая сила — наше право по рождению!', 24330),
(115023, 'ruRU', '', 'Слева от меня ты увидишь один из наших садов.', 24330),
(115025, 'ruRU', '', 'Если ты хоть немного знаком с процессом винодельчества, то знаешь, что сок необходимо дать настояться для брожения.', 24330),
(115026, 'ruRU', '', 'В этом здании разводят вид деревьев, что приносят особо сладкие плоды — те, что ты попробовал в Настойке.', 24330),
(115027, 'ruRU', '', 'Кирин-Тор всецело поддерживает новую Тирисгарду, $n.', 24330),
(115028, 'ruRU', '', 'Здания перед тобой вмещают наши предприятия по разливу.', 24330),
(115029, 'ruRU', '', 'Каждая бутылка запечатана магией, чтобы не дать сущности Ночного Колодца рассеяться.', 24330),
(115030, 'ruRU', '', 'Бочонок аркового вина с нашего виноградника можно безопасно хранить сотнями лет!', 24330),
(115031, 'ruRU', '', 'Впереди ты увидишь наш распределительный склад.', 24330),
(115032, 'ruRU', '', 'Здесь мы организуем отправку сотен бочек и бочонков аркового вина в город.', 24330),
(115033, 'ruRU', '', 'Магистрикс очень пристально следит за этой деятельностью—', 24330),
(115034, 'ruRU', '', 'Не трогайте его!', 24330),
(115035, 'ruRU', '', 'Мне так жаль — прошу, прости эту ошибку. Я лично прослежу, чтобы это не повторилось.', 24330),
(115036, 'ruRU', '', 'На чём мы остановились?', 24330),
(115037, 'ruRU', '', 'Я считаю, что Кирин-Тор должен принимать помощь со всех сторон, если мы хотим победить Пылающий Легион.', 24330),
(115038, 'ruRU', '', 'За этим мостом находится важнейшая часть нашего процесса винодельчества.', 24330),
(115039, 'ruRU', '', 'Именно здесь мы насыщаем наше вино сущностью Ночного Колодца, что придаёт ему восстанавливающие свойства, которыми наслаждается наш народ.', 24330),
(115040, 'ruRU', '', 'И здесь я тебя оставляю. Мне нужно подготовить следующее мероприятие.', 24330),
(115041, 'ruRU', '', 'Нам предстоит многое сделать, если мы хотим победить Пылающий Легион. Я не позволю им разрушить мой город во второй раз.', 24330),
(115042, 'ruRU', '', 'Я встречу тебя на следующей станции. Моя помощница Сильверин с радостью покажет тебе, как работает процесс настаивания.', 24330),
(115043, 'ruRU', '', 'Правда ли, что Туралион жив?', 24330),
(115045, 'ruRU', '', 'Клянусь Светом... что это значит для Азерота?', 24330),
(115047, 'ruRU', '', 'Наше любимое дитя.', 24330),
(115054, 'ruRU', '', 'Азерот — последний свет надежды, Аратор. Сражайся, или всё потеряно.', 24330),
(115062, 'ruRU', '', 'Не думали ж, что Тёмное Железо позволит вам, остолопам, забрать всё веселье себе одним, а?', 24330);
